<?php
declare(strict_types=1); namespace Wms;
final class WorkflowService extends Service {
 public function __construct(Database$db,Audit$a,private EntityService$entities){parent::__construct($db,$a);}
 public function prn(string$a,array$p,array$u):array{if($a==='list'){[$page,$size,$offset]=Util::page($p);$all=$this->entities->prnRows();$q=mb_strtolower(Util::text($p['search']??''));if($q)$all=array_values(array_filter($all,fn($x)=>str_contains(mb_strtolower(implode(' ',[$x['number'],$x['deliveryNumber'],$x['vehicleNumber'],$x['status']])),$q)));$total=count($all);return['items'=>array_slice($all,$offset,$size),'page'=>$page,'pageSize'=>$size,'total'=>$total,'pages'=>(int)ceil($total/$size)];}if($a==='create')return$this->db->transaction(function()use($p,$u){$number=Util::text($p['number']??'');$this->one('SELECT id FROM deliveries WHERE id=? AND deleted_at IS NULL',[$p['deliveryId']??''],'Доставка не найдена');if(!$number)throw new ApiException('VALIDATION','Укажите номер PRN');if($this->db->one('SELECT id FROM prns WHERE number=?',[$number]))throw new ApiException('DUPLICATE','PRN с таким номером уже существует');$id=Util::uuid();$this->db->exec('INSERT INTO prns(id,number,delivery_id,created_at,created_by) VALUES(?,?,?,?,?)',[$id,$number,$p['deliveryId'],Util::now(),$u['id']]);$this->audit->log($u,'CREATE','prn',$id,[],['number'=>$number]);return$this->entities->prnRows('p.id=?',[$id])[0];});$row=$this->one('SELECT * FROM prns WHERE id=? AND deleted_at IS NULL',[$p['id']??''],'PRN не найден');if($a==='get')return$this->detail($row);return$this->db->transaction(function()use($a,$p,$u,$row){$field=match($a){'startReception'=>'reception_started_at','ready'=>'ready_at','close'=>'closed_at',default=>throw new ApiException('ROUTE','Неизвестное действие')};if($a==='startReception'&&!$this->db->one('SELECT id FROM prn_items WHERE prn_id=? AND deleted_at IS NULL LIMIT 1',[$row['id']]))throw new ApiException('VALIDATION','Сначала добавьте товары');if($a==='ready'){ $bad=$this->db->one('SELECT id FROM prn_items WHERE prn_id=? AND deleted_at IS NULL AND planned<>received LIMIT 1',[$row['id']]);if($bad&&!Util::bool($p['confirmDiscrepancy']??false))throw new ApiException('DISCREPANCY','Приёмка имеет расхождения. Подтвердите переход явно.');}if($a==='close'&&$this->remaining($row['id'])>0)throw new ApiException('VALIDATION','Нельзя закрыть PRN: не весь товар размещён');$this->conflict($this->db->exec("UPDATE prns SET $field=COALESCE($field,?),version=version+1 WHERE id=? AND version=?",[Util::now(),$row['id'],(int)$p['version']]));$this->audit->log($u,strtoupper($a),'prn',$row['id'],$row,[]);return[];});}
 public function items(string$a,array$p,array$u):array{if($a==='import')return$this->db->transaction(function()use($p,$u){$prn=$this->one('SELECT id FROM prns WHERE id=? AND deleted_at IS NULL',[$p['prnId']??''],'PRN не найден');$items=$p['items']??[];if(!is_array($items)||!count($items)||count($items)>500)throw new ApiException('VALIDATION','Передайте от 1 до 500 позиций');$seen=[];$s=$this->db->pdo()->prepare('INSERT INTO prn_items(id,prn_id,name,planned,received,created_at,updated_at) VALUES(?,?,?,?,0,?,?)');foreach($items as$x){$name=Util::text($x['name']??'');$qty=Util::qty($x['quantity']??0);$key=mb_strtolower($name);if(!$name||isset($seen[$key]))throw new ApiException('DUPLICATE','Пустой или повторяющийся товар: '.$name);$seen[$key]=1;$s->execute([Util::uuid(),$prn['id'],$name,$qty,Util::now(),Util::now()]);}$this->audit->log($u,'IMPORT_ITEMS','prn',$prn['id'],[],['count'=>count($items)]);return['count'=>count($items)];});if($a==='receive')return$this->db->transaction(function()use($p,$u){$i=$this->one('SELECT * FROM prn_items WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$p['id']??''],'Позиция не найдена');$received=filter_var($p['received']??null,FILTER_VALIDATE_INT);if($received===false||$received<0)throw new ApiException('VALIDATION','Принятое количество должно быть целым и неотрицательным');$used=(int)$this->db->one('SELECT GREATEST(COALESCE((SELECT SUM(quantity) FROM pallet_items WHERE prn_item_id=? AND deleted_at IS NULL),0),COALESCE((SELECT SUM(quantity) FROM placements WHERE prn_item_id=?),0)) n',[$i['id'],$i['id']])['n'];if($received<$used)throw new ApiException('VALIDATION','Количество нельзя уменьшить ниже уже распределённого');$this->conflict($this->db->exec('UPDATE prn_items SET received=?,updated_at=?,version=version+1 WHERE id=? AND version=?',[$received,Util::now(),$i['id'],(int)$p['version']]));$this->audit->log($u,'RECEIVE','prn',$i['prn_id'],['received'=>$i['received']],['received'=>$received]);return[];});throw new ApiException('ROUTE','Неизвестное действие');}
 public function pallet(string$a,array$p,array$u):array{if($a!=='create')throw new ApiException('ROUTE','Неизвестное действие');return$this->db->transaction(function()use($p,$u){$prn=$this->one('SELECT * FROM prns WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$p['prnId']??''],'PRN не найден');$items=$p['items']??[];if(!$items)throw new ApiException('VALIDATION','Добавьте товары в палету');foreach($items as$x){$i=$this->one('SELECT * FROM prn_items WHERE id=? AND prn_id=? FOR UPDATE',[$x['prnItemId']??'',$prn['id']],'Позиция PRN не найдена');$q=Util::qty($x['quantity']??0);$used=(int)$this->db->one('SELECT COALESCE(SUM(quantity),0)n FROM pallet_items WHERE prn_item_id=? AND deleted_at IS NULL',[$i['id']])['n'];if($used+$q>(int)$i['received'])throw new ApiException('VALIDATION','В палету нельзя добавить больше доступного: '.$i['name']);}$this->db->exec("INSERT INTO settings(`key`,`value`,updated_at) VALUES('pallet_sequence','1',?) ON DUPLICATE KEY UPDATE `value`=LAST_INSERT_ID(`value`+1),updated_at=VALUES(updated_at)",[Util::now()]);$seq=(int)$this->db->pdo()->lastInsertId();if(!$seq)$seq=1;$id=Util::uuid();$number='PLT-'.str_pad((string)$seq,6,'0',STR_PAD_LEFT);$this->db->exec('INSERT INTO pallets(id,number,prn_id,status,created_at,created_by,completed_at) VALUES(?,?,?,?,?,?,?)',[$id,$number,$prn['id'],'Сформирована',Util::now(),$u['id'],Util::now()]);foreach($items as$x)$this->db->exec('INSERT INTO pallet_items(id,pallet_id,prn_item_id,quantity,created_at) VALUES(?,?,?,?,?)',[Util::uuid(),$id,$x['prnItemId'],Util::qty($x['quantity']),Util::now()]);$this->audit->log($u,'CREATE_PALLET','prn',$prn['id'],[],['pallet'=>$number,'items'=>$items]);return['id'=>$id,'number'=>$number,'version'=>1];});}
 private function remaining(string$id):int{return(int)$this->db->one('SELECT COALESCE(SUM(i.received),0)-COALESCE((SELECT SUM(quantity) FROM placements WHERE prn_id=?),0)n FROM prn_items i WHERE i.prn_id=? AND i.deleted_at IS NULL',[$id,$id])['n'];}
 public function detail(array$p):array{$prn=$this->entities->prnRows('p.id=?',[$p['id']])[0];$rows=$this->db->all('SELECT i.*,COALESCE((SELECT SUM(quantity) FROM pallet_items pi WHERE pi.prn_item_id=i.id AND pi.deleted_at IS NULL),0)palleted,COALESCE((SELECT SUM(quantity) FROM placements x WHERE x.prn_item_id=i.id),0)placed FROM prn_items i WHERE i.prn_id=? AND i.deleted_at IS NULL ORDER BY i.created_at',[$p['id']]);$items=array_map(function($i){$i['unpacked']=(int)$i['received']-(int)$i['palleted'];$i['remaining_receive']=max(0,(int)$i['planned']-(int)$i['received']);$i['remaining_place']=max(0,(int)$i['received']-(int)$i['placed']);return$this->camel($i);},$rows);$pallets=array_map(function($x){$x=$this->camel($x);$x['items']=array_map(fn($i)=>$this->camel($i),$this->db->all('SELECT pi.*,i.name FROM pallet_items pi JOIN prn_items i ON i.id=pi.prn_item_id WHERE pi.pallet_id=? AND pi.deleted_at IS NULL',[$x['id']]));return$x;},$this->db->all('SELECT * FROM pallets WHERE prn_id=? AND deleted_at IS NULL ORDER BY created_at',[$p['id']]));$history=array_map(fn($x)=>$this->camel($x),$this->db->all('SELECT * FROM audit_log WHERE entity_id=? ORDER BY created_at DESC LIMIT 100',[$p['id']]));$cells=array_map(fn($x)=>$this->camel($x),$this->db->all('SELECT id,name FROM cells WHERE deleted_at IS NULL ORDER BY name'));return compact('prn','items','pallets','history','cells');}
}
